<?php
require_once __DIR__.'/../app/manager.php';
$db=app_db(); manager_install($db);
$manager=manager_current($db);
if(!$manager){header('Location: '.app_url('gerente/login.php'));exit;}
$managerId=(int)$manager['id'];$error='';$notice='';$demoCredentials=null;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    try{
        if(!app_check_csrf())throw new InvalidArgumentException('Formulário expirado. Recarregue a página.');
        $action=app_input('action');
        if($action==='partner'){
            if(!is_numeric(app_input('manager_percent'))||!is_numeric(app_input('influencer_percent')))throw new InvalidArgumentException('Informe os dois percentuais.');
            manager_partner_create($db,$managerId,app_input('name'),(float)app_input('manager_percent'),(float)app_input('influencer_percent'));$notice='Link exclusivo criado.';
        }elseif($action==='partner_update'){
            $id=(int)app_input('id');$mp=(float)app_input('manager_percent');$ip=(float)app_input('influencer_percent');
            if($id<1||!is_numeric(app_input('manager_percent'))||!is_numeric(app_input('influencer_percent'))||$mp<0||$ip<0||abs($mp+$ip-MANAGER_BUDGET_PERCENT)>.0001)throw new InvalidArgumentException('A divisão precisa somar exatamente 70%.');
            app_query($db,'UPDATE manager_partners SET manager_percent=?,influencer_percent=? WHERE id=? AND manager_id=?',[(string)$mp,(string)$ip,(string)$id,(string)$managerId]);$notice='Divisão salva para os próximos depósitos.';
        }elseif($action==='partner_toggle'){
            app_query($db,'UPDATE manager_partners SET active=1-active WHERE id=? AND manager_id=?',[(string)(int)app_input('id'),(string)$managerId]);$notice='Status do link atualizado.';
        }elseif($action==='demo_auto'){
            $quantity=filter_var(app_input('quantity'),FILTER_VALIDATE_INT);if($quantity===false||$quantity<1||$quantity>10)throw new InvalidArgumentException('Escolha de 1 a 10 contas por vez.');
            for($i=0;$i<$quantity;$i++)$demoCredentials[]=manager_demo_create_auto($db,$managerId,app_input('initial_balance'),app_input('name_prefix'),app_input('password_prefix'));
            $notice=$quantity===1?'Conta demo criada.':'Contas demo criadas.';
        }elseif($action==='demo_update'){
            $email=app_input('email');$password=app_input('password');manager_demo_update($db,$managerId,$email,app_input('name'),app_input('balance'),$password);
            if($password!=='')$demoCredentials=[['name'=>app_input('name'),'email'=>$email,'password'=>$password]];$notice='Conta demo atualizada.';
        }elseif($action==='payout'){
            $nonce=app_input('nonce');if($nonce===''||empty($_SESSION['manager_payout_nonce'])||!hash_equals($_SESSION['manager_payout_nonce'],$nonce))throw new InvalidArgumentException('Esta solicitação já foi enviada. Atualize a página.');
            unset($_SESSION['manager_payout_nonce']);manager_payout_request($db,$managerId,app_input('amount'),app_input('pix_key'));$notice='Solicitação enviada para análise.';
        }elseif($action==='notifications_save'){
            $url=trim(app_input('webhook_url'));if(!manager_pushcut_url_valid($url))throw new InvalidArgumentException('Cole uma URL válida do Pushcut: https://api.pushcut.io/.../notifications/...');
            app_query($db,'INSERT INTO manager_notification_settings(manager_id,webhook_url,event_signup,event_deposit,event_sale) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE webhook_url=VALUES(webhook_url),event_signup=VALUES(event_signup),event_deposit=VALUES(event_deposit),event_sale=VALUES(event_sale)',[(string)$managerId,manager_secret_encrypt($url),isset($_POST['event_signup'])?'1':'0',isset($_POST['event_deposit'])?'1':'0',isset($_POST['event_sale'])?'1':'0']);
            try{manager_pushcut_flush($db);}catch(Throwable $pushError){error_log('manager notification flush: '.$pushError->getMessage());}
            $notice='Notificações salvas.';
        }elseif($action==='notifications_test'){
            $url=trim(app_input('webhook_url'));if(!manager_pushcut_url_valid($url))throw new InvalidArgumentException('Cole uma URL válida do Pushcut antes de testar.');
            if(!manager_pushcut_send($url,'Subway Run · Teste','Conexão do Pushcut configurada para '.$manager['name'].'.'))throw new RuntimeException('O Pushcut não confirmou o envio. Confira a URL e tente novamente.');$notice='Notificação de teste enviada ao Pushcut.';
        }elseif($action==='notifications_remove'){
            app_query($db,'DELETE FROM manager_notification_settings WHERE manager_id=?',[(string)$managerId]);app_query($db,'DELETE FROM manager_notification_outbox WHERE manager_id=?',[(string)$managerId]);$notice='Integração Pushcut removida.';
        }elseif($action==='profile'){
            $name=trim(app_input('name'));if(strlen($name)<2||strlen($name)>120)throw new InvalidArgumentException('Informe um nome entre 2 e 120 caracteres.');
            $account=app_query($db,'SELECT password_hash FROM manager_accounts WHERE id=? AND active=1',[(string)$managerId])->get_result()->fetch_assoc();
            if(!$account)throw new InvalidArgumentException('A conta não está disponível.');
            $current=app_input('current_password');$new=app_input('new_password');
            if($new!==''&&(!password_verify($current,(string)$account['password_hash'])||strlen($new)<10||strlen($new)>72))throw new InvalidArgumentException('Confira a senha atual. A nova senha deve ter de 10 a 72 caracteres.');
            $newHash=$new!==''?password_hash($new,PASSWORD_DEFAULT):'';
            app_query($db,'UPDATE manager_accounts SET name=?'.($new!==''?',password_hash=?':'').' WHERE id=?', $new!==''?[$name,$newHash,(string)$managerId]:[$name,(string)$managerId]);
            if($new!==''){$_SESSION['manager_auth_hash']=app_password_fingerprint($newHash);app_auth_remember_install($db);app_query($db,"DELETE FROM auth_remember_tokens WHERE scope='manager' AND subject=?",[(string)$managerId]);app_auth_remember_clear_cookie('manager');}
            $notice='Perfil atualizado.';$manager['name']=$name;
        }else throw new InvalidArgumentException('Ação inválida.');
    }catch(mysqli_sql_exception $e){error_log('manager panel: '.$e->getMessage());$error=$e->getCode()===1062?'Este cadastro já existe.':'Não foi possível salvar. Tente novamente.';}
    catch(InvalidArgumentException $e){$error=$e->getMessage();}
    catch(Throwable $e){error_log('manager panel: '.$e->getMessage());$error=$e instanceof RuntimeException?$e->getMessage():'Não foi possível concluir a operação.';}
}
$managerIdString=(string)$managerId;
$partners=app_query($db,'SELECT p.*,(SELECT COUNT(*) FROM manager_referrals r WHERE r.partner_id=p.id) leads FROM manager_partners p WHERE p.manager_id=? ORDER BY p.id DESC',[$managerIdString])->get_result()->fetch_all(MYSQLI_ASSOC);
$demos=app_query($db,"SELECT d.email,d.display_name,d.password_encrypted,d.created_at,a.saldo,a.telefone FROM manager_demos d JOIN appconfig a ON a.email COLLATE utf8mb4_unicode_ci=d.email COLLATE utf8mb4_unicode_ci AND a.demo=1 WHERE d.manager_id=? ORDER BY d.created_at DESC LIMIT 100",[$managerIdString])->get_result()->fetch_all(MYSQLI_ASSOC);
foreach($demos as &$demoRow)$demoRow['password_visible']=manager_demo_decrypt_password((string)($demoRow['password_encrypted']??''));unset($demoRow);
$referrals=app_query($db,"SELECT r.email,r.influencer_email,r.created_at,p.id partner_id,p.name partner_name,p.influencer_email root_email,a.id user_id,a.nome,a.telefone,a.data_cadastro,a.saldo,a.depositou,a.comissaofake,a.status_primeiro_deposito FROM manager_referrals r JOIN manager_partners p ON p.id=r.partner_id LEFT JOIN appconfig a ON a.email COLLATE utf8mb4_unicode_ci=r.email COLLATE utf8mb4_unicode_ci WHERE p.manager_id=? ORDER BY r.created_at DESC LIMIT 2000",[$managerIdString])->get_result()->fetch_all(MYSQLI_ASSOC);
$levelByEmail=[];$rowsByParent=[];foreach($referrals as $r){$parent=strtolower((string)($r['influencer_email']??''));$rowsByParent[$parent][]=$r;}
foreach($partners as $partner){$frontier=[strtolower((string)($partner['influencer_email']??''))];for($level=1;$level<=3;$level++){$next=[];foreach($frontier as $parent){foreach($rowsByParent[$parent]??[] as $r){$email=strtolower((string)$r['email']);if(!isset($levelByEmail[$email])){$levelByEmail[$email]=$level;$next[]=$email;}}}$frontier=$next;if(!$frontier)break;}}
$commissionRows=app_query($db,'SELECT c.*,p.name partner_name FROM manager_commissions c JOIN manager_partners p ON p.id=c.partner_id WHERE c.manager_id=? ORDER BY c.created_at DESC LIMIT 500',[$managerIdString])->get_result()->fetch_all(MYSQLI_ASSOC);
$commByEmail=[];foreach($commissionRows as $c){$email=strtolower((string)($c['referred_email']??''));if($email!=='')$commByEmail[$email]=($commByEmail[$email]??0)+(float)$c['manager_amount'];}
$referralCount=count($referrals);$referralVolume=0.0;foreach($referrals as $r)$referralVolume+=(float)($r['depositou']??0);
$totals=app_query($db,'SELECT COUNT(*) deposits,COALESCE(SUM(deposit_amount),0) volume,COALESCE(SUM(manager_amount),0) manager_total FROM manager_commissions WHERE manager_id=?',[$managerIdString])->get_result()->fetch_assoc();
$trendRows=app_query($db,'SELECT DATE(created_at) AS chart_date,COALESCE(SUM(manager_amount),0) AS commission,COALESCE(SUM(deposit_amount),0) AS volume FROM manager_commissions WHERE manager_id=? AND created_at>=CURDATE()-INTERVAL 6 DAY GROUP BY DATE(created_at)',[$managerIdString])->get_result()->fetch_all(MYSQLI_ASSOC);
$trendByDay=[];foreach($trendRows as $row)$trendByDay[$row['chart_date']]=$row;
$trendDays=[];for($day=6;$day>=0;$day--){$date=date('Y-m-d',strtotime('-'.$day.' days'));$trendDays[]=['label'=>date('d/m',strtotime($date)),'commission'=>(float)($trendByDay[$date]['commission']??0),'volume'=>(float)($trendByDay[$date]['volume']??0)];}
$available=manager_payout_available($db,$managerId);$payouts=app_query($db,'SELECT id,amount,status,created_at FROM manager_payout_requests WHERE manager_id=? ORDER BY id DESC LIMIT 30',[$managerIdString])->get_result()->fetch_all(MYSQLI_ASSOC);
$notification=app_query($db,'SELECT webhook_url,event_signup,event_deposit,event_sale FROM manager_notification_settings WHERE manager_id=? LIMIT 1',[$managerIdString])->get_result()->fetch_assoc()?:['webhook_url'=>'','event_signup'=>1,'event_deposit'=>1,'event_sale'=>1];$notification['webhook_url']=manager_secret_decrypt((string)$notification['webhook_url']);
$host=(string)($_SERVER['HTTP_HOST']??'localhost');if(!preg_match('/^[a-zA-Z0-9.:-]+$/D',$host))$host='localhost';$origin=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.$host;$managerInitial=strtoupper(substr((string)$manager['name'],0,1));
$money=static fn($v):string=>'R$ '.number_format((float)$v,2,',','.');$statusLabel=static fn($s):string=>['PENDING'=>'Pendente','PAID'=>'Aprovado','REJECTED'=>'Recusado'][$s]??$s;
$renderTrend=static function(array $days,string $key) use($money):string {
    $max=1.0;foreach($days as $day)$max=max($max,(float)$day[$key]);
    $html='<div class="trend-chart" role="img" aria-label="Valores diários dos últimos sete dias">';
    foreach($days as $day){$value=(float)$day[$key];$height=$value>0?max(5,min(100,$value/$max*100)):2;$label=app_escape($day['label'].' · '.$money($value));$html.='<div class="trend-bar" title="'.$label.'"><span style="height:'.number_format($height,1,'.','').'%"></span><small>'.app_escape($day['label']).'</small></div>';}
    return $html.'</div>';
};
$maxVolume=max(10000.0,(float)($totals['volume']??0));$volumePct=min(100,(float)($totals['volume']??0)/$maxVolume*100);
$_SESSION['manager_payout_nonce']=bin2hex(random_bytes(24));$csrf=app_csrf();
?>
