<section class="view active" id="view-dashboard" data-section="dashboard"><div class="view-heading"><div><small>VISÃO GERAL</small><h1>Olá, <?=app_escape($manager['name'])?></h1><p>Acompanhe sua rede e as comissões geradas.</p></div><button class="btn outline" type="button" data-refresh>Atualizar</button></div><div class="metric-grid"><article class="metric-card green-card"><small>SALDO DISPONÍVEL</small><strong><?=$money($available)?></strong><a href="#withdraw" data-view="withdraw">Solicitar saque →</a><svg viewBox="0 0 260 46" aria-hidden="true"><path d="M0 38 C30 34 36 27 60 37 S92 45 119 34 S158 39 180 28 S215 41 260 5"/></svg></article><article class="metric-card"><small>TOTAL COMISSÕES</small><strong><?=$money($totals['manager_total']??0)?></strong><a href="#commissions" data-view="commissions">Comissão recebida →</a><svg viewBox="0 0 260 46" aria-hidden="true"><path d="M0 32 C35 28 40 38 74 31 S116 24 148 32 S205 35 260 9"/></svg></article><article class="metric-card"><small>INDICADOS NA REDE</small><strong><?=$referralCount?></strong><a href="#referrals" data-view="referrals">Ver usuários da rede →</a><svg viewBox="0 0 260 46" aria-hidden="true"><path d="M0 36 C39 35 57 40 85 34 S134 36 162 28 S215 33 260 11"/></svg></article><article class="metric-card blue-card"><small>DEPÓSITOS NA REDE</small><strong><?=$money($referralVolume)?></strong><a href="#referrals" data-view="referrals">Depósitos aprovados →</a><svg viewBox="0 0 260 46" aria-hidden="true"><path d="M0 29 C30 40 56 19 83 29 S124 36 157 28 S215 32 260 10"/></svg></article></div><div class="panel-grid"><article class="surface"><div class="surface-title"><h2>Comissões recebidas</h2><span class="legend green-dot">Comissão recebida</span></div><div class="chart-bars" data-chart="commission"><span><?=$money($totals['manager_total']??0)?></span><?=$renderTrend($trendDays,'commission')?><small>Comissões registradas em depósitos aprovados</small></div></article><article class="surface"><div class="surface-title"><h2>Depósitos da rede</h2><span class="legend blue-dot">Depósitos aprovados</span></div><div class="chart-bars blue-chart"><span><?=$money($referralVolume)?></span><?=$renderTrend($trendDays,'volume')?><small>Volume depositado por seus indicados</small></div></article></div><article class="surface"><div class="surface-title"><h2>Top indicados</h2><a class="text-action" href="#referrals" data-view="referrals">Ver rede completa →</a></div><div class="table-scroll"><table><thead><tr><th>POS.</th><th>INDICADO</th><th>CONTATO</th><th>NÍVEL</th><th>DEPÓSITOS</th><th>COMISSÃO GERADA</th><th></th></tr></thead><tbody><?php $top=$referrals;usort($top,static fn($a,$b)=>(float)($b['depositou']??0)<=>(float)($a['depositou']??0));foreach(array_slice($top,0,10) as $i=>$r):?><tr><td><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></td><td><strong><?=app_escape($r['nome']?:'Usuário')?></strong></td><td><?=app_escape($r['telefone']?:'—')?></td><td><span class="level-tag">N<?= (int)($levelByEmail[strtolower($r['email'])]??1) ?></span></td><td><?=$money($r['depositou']??0)?></td><td><?=$money($commByEmail[strtolower($r['email'])]??0)?></td><td><button class="btn small outline" type="button" data-details="<?=app_escape($r['email'])?>">Detalhes</button></td></tr><?php endforeach;?><?php if(!$top):?><tr><td colspan="7" class="empty-row">Seus indicados aparecerão aqui.</td></tr><?php endif;?></tbody></table></div></article></section>
