de></td><td><?=$money($d['saldo'])?></td><td><button class="btn small outline edit-demo" type="button" data-email="<?=app_escape($d['email'])?>" data-name="<?=app_escape($d['display_name']?:'Conta demo')?>" data-balance="<?=app_escape($d['saldo'])?>">Editar</button></td></tr><?php endforeach;?><?php if(!$demos):?><tr><td colspan="6" class="empty-row">Crie a primeira conta demo acima.</td></tr><?php endif;?></tbody></table></div></article></section>
<section class="view" id="view-commissions" data-section="commissions"><div class="view-heading"><div><small>OPERACIONAL</small><h1>Comissões</h1><p>Valores calculados dos depósitos confirmados da sua rede.</p></div><span class="count-pill"><?=count($commissionRows)?> registros</span></div><div class="metric-grid two-metrics"><article class="metric-card"><small>TOTAL DE COMISSÕES</small><strong><?=$money($totals['manager_total']??0)?></strong><span>Créditos atribuídos a você</span></article><article class="metric-card"><small>VOLUME DE DEPÓSITOS</small><strong><?=$money($totals['volume']??0)?></strong><span><?= (int)($totals['deposits']??0) ?> depósitos confirmados</span></article></div><article class="surface"><div class="table-scroll"><table><thead><tr><th>INDICADO</th><th>DEPÓSITO</th><th>SUA PARTE</th><th>DIVISÃO</th><th>DATA</th></tr></thead><tbody><?php foreach($commissionRows as $c):$person='';foreach($referrals as $ref)if(strcasecmp($ref['email'],$c['referred_email']??'')===0){$person=(string)$ref['nome'];break;}?><tr><td><?=app_escape($person?:'Depósito da rede')?></td><td><?=$money($c['deposit_amount'])?></td><td class="money-green"><?=$money($c['manager_amount'])?></td><td><?=number_format((float)$c['manager_percent'],2,',','.')?>%</td><td><?=app_escape(date('d/m/Y H:i',strtotime($c['created_at'])?:time()))?></td></tr><?php endforeach;?><?php if(!$commissionRows):?><tr><td colspan="5" class="empty-row">Nenhuma comissão registrada ainda.</td></tr><?php endif;?></tbody></table></div></article></section>
<section class="view" id="view-links" data-section="links"><div class="view-heading"><div><small>REDE</small><h1>Link de indicação</h1><p>Crie links separados para influenciadores e acompanhe cada parceria.</p></div></div><article class="surface"><div class="surface-title"><h2>Criar link exclusivo</h2></div><p class="muted">Seu orçamento por parceria é 70%. Divida essa parte entre você e o influenciador.</p><form class="form-grid link-create-grid" method="post"><input type="hidden" name="csrf" value="<?=app_escape($csrf)?>"><input type="hidden" name="action" value="partner"><label>Nome do influenciador<input name="name" maxlength="120" required></label><label>Sua parte (%)<input name="manager_percent" type="number" min="0" max="70" step="0.01" value="35" required></label><label>Parte do influenciador (%)<input name="influencer_percent" type="number" min="0" max="70" step="0.01" value="35" required></label><button class="btn green" type="submit">＋ Criar link</button><div class="budget-meter"><span>ORÇAMENTO DA PARCERIA</span><strong><b data-budget-sum>70</b>% / 70%</strong></div></form></article><div class="partner-grid"><?php foreach($partners as $p):$link=$origin.app_url('cadastrar/?ref='.$p['code']);?><article class="surface partner-card"><div class="surface-title"><div><small class="overline">LINK DE INDICAÇÃO</small><h2><?=app_escape($p['name'])?></h2></div><span class="state-tag <?=$p['active']?'state-on':'state-off'?>"><?=$p['active']?'ATIVO':'PAUSADO'?></span></div><p class="muted"><?=(int)$p['leads']?> cadastros vinculados</p><div class="copy-row"><input readonly value="<?=app_escape($link)?>"><button class="btn green small" type="button" data-copy-text="<?=app_escape($link)?>">Copiar</button></div><form class="form-grid split-edit" method="post"><input type="hidden" name="csrf" value="<?=app_escape($csrf)?>"><input type="hidden" name="action" value="partner_update"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><label>Sua parte<input name="manager_percent" type="number" min="0" max="70" step="0.01" value="<?=app_escape($p['manager_percent'])?>"></label><label>Influenciador<input name="influencer_percent" type="number" min="0" max="70" step="0.01" value="<?=app_escape($p['influencer_percent'])?>"></label><button class="btn outline small" type="submit">Salvar divisão</button></form><form method="post" class="partner-toggle"><input type="hidden" name="csrf" value="<?=app_escape($csrf)?>"><input type="hidden" name="action" value="partner_toggle"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="btn small <?=$p['active']?'danger-outline':'outline'?>" type="submit"><?=$p['active']?'Pausar link':'Ativar link'?></button></form></article><?php endforeach;?><?php if(!$partners):?><article class="surface empty-row">Você ainda não criou um link de influenciador.</article><?php endif;?></div></section>
<section class="view" id="view-referrals" data-section="referrals"><div class="view-heading"><div><small>REDE</small><h1>Indicados</h1><p>Consulte os cadastros, níveis, depósitos e comissões associados às suas parcerias.</p></div><button class="btn outline" type="button" data-refresh>Atualizar</button></div><div class="metric-grid four-metrics"><article class="metric-card"><small>TOTAL NA REDE</small><strong><?=$referralCount?></strong><span>indicações vinculadas</span></article><article class="metric-card"><small>DEPÓSITOS NA REDE</small><strong><?=$money($referralVolume)?></strong><span>volume informado pelas contas</span></article><article class="metric-card"><small>SUA COMISSÃO</small><strong><?=$money($totals['manager_total']??0)?></strong><span>soma de depósitos registrados</span></article><article class="metric-card"><small>COM DEPÓSITO</small><strong><?=(int)($totals['deposits']??0)?></strong><span>operações confirmadas</span></article></div><article class="surface"><div class="toolbar"><input class="table-search" data-search-table="referral-table" placeholder="Buscar por nome ou telefone"><div class="filter-pills"><button class="selected" type="button" data-level-filter="all">Geral</button><button type="button" data-level-filter="1">N1</button><button type="button" data-level-filter="2">N2</button><button type="button" data-level-filter="3">N3</button></div></div><div class="table-scroll"><table id="referral-table"><thead><tr><th>NÍVEL</th><th>NOME</th><th>TELEFONE</th><th>CADASTRO</th><th>TOTAL DEPOSITADO</th><th>COMISSÃO GERADA</th><th>COM DEPÓSITO</th><th>AÇÕES</th></tr></thead><tbody><?php foreach($referrals as $r):$level=(int)($levelByEmail[strtolower($r['email'])]??1);?><tr data-level="<?=$level?>" data-search="<?=app_escape(strtolower(($r['nome']??'').' '.($r['telefone']??'').' '.$r['email']))?>"><td><span class="level-tag">N<?=$level?></span></td><td><strong><?=app_escape($r['nome']?:'Usuário')?></strong></td><td><?=app_escape($r['telefone']?:'—')?></td><td><?=app_escape($r['data_cadastro']?:'—')?></td><td><?=$money($r['depositou']??0)?></td><td><?=$money($commByEmail[strtolower($r['email'])]??0)?></td><td><span class="state-tag <?=($r['status_primeiro_deposito']??'0')==='1'?'state-on':'state-off'?>"><?=($r['status_primeiro_deposito']??'0')==='1'?'SIM':'NÃO'?></span></td><td><button class="btn green small" type="button" data-details="<?=app_escape($r['email'])?>">Detalhes</button></td></tr><?php endforeach;?><?php if(!$referrals):?><tr><td colspan="8" class="empty-row">Ainda não há indicados associados aos seus links.</td></tr><?php endif;?></tbody></table></div></article></section>
<section class="view" id="view-withdraw" data-section="withdraw"><div class="view-heading"><div><small>CARTEIRA</small><h1>Sacar</h1><p>Solicite a retirada das comissões disponíveis. A aprovação é feita pela administração.</p></div></div><div class="metric-grid two-metrics"><article class="metric-card green-card"><small>SALDO DISPONÍVEL PARA SAQUE</small><strong><?=$money($available)?></strong><a href="#withdraw-form" class="btn green" style="margin-top:14px">Solicitar saque</a></article><article class="metric-card"><small>TOTAL SACADO</small><strong><?=$money(array_sum(array_map(static fn($p)=>in_array($p['status'],['PAID','APROVED','APPROVED'],true)?(float)$p['amount']:0,$payouts)))?></strong><span>Solicitações já aprovadas</span></article></div><article class="surface" id="withdraw-form"><div class="surface-title"><h2>Nova solicitação</h2></div><form class="form-grid payout-grid" method="post"><input type="hidden" name="csrf" value="<?=app_escape($csrf)?>"><input type="hidden" name="nonce" value="<?=app_escape($_SESSION['manager_payout_nonce'])?>"><input type="hidden" name="action" value="payout"><label>Valor (R$)<input name="amount" type="number" min="1" max="<?=app_escape($available)?>" step="0.01" required></label><label>Chave PIX<input name="pix_key" maxlength="77" required placeholder="CPF, telefone, e-mail ou chave aleatória"></label><button class="btn green" type="submit" <?= (float)$available<1?'disabled':'' ?>>Enviar solicitação</button></form></article><article class="surface"><div class="surface-title"><h2>Histórico de saques</h2><span class="count-pill"><?=count($payouts)?> solicitações</span></div><div class="table-scroll"><table><thead><tr><th>VALOR</th><th>CHAVE PIX</th><th>STATUS</th><th>DATA</th></tr></thead><tbody><?php foreach($payouts as $p):?><tr><td class="money-green"><?=$money($p['amount'])?></td><td>••••••••</td><td><span class="state-tag state-<?=strtolower(app_escape($p['status']))?>"><?=app_escape($statusLabel($p['status']))?></span></td><td><?=app_escape($p['created_at'])?></td></tr><?php endforeach;?><?php if(!$payouts):?><tr><td colspan="4" class="empty-row">Nenhuma solicitação de saque enviada.</td></tr><?php endif;?></tbody></table></div></article></section>
<section class="view" id="view-notifications" data-section="notifications"><div class="view-heading"><div><small>CONTA</small><h1>Notificações</h1><p>Configure alertas no seu iPhone via Pushcut.</p></div></div><div class="notice-hero"><span class="notice-icon">N</span><div><h2>Notificações no iPhone</h2><p>Receba alertas instantâneos quando algo acontecer na sua rede. Utiliza o app <strong>Pushcut</strong>.</p></div></div><article class="surface"><h2>Como configurar em 3 passos</h2><ol class="steps"><li>Instale o app <strong>Pushcut</strong> na App Store (iPhone).</li><li>Abra o app → <strong>Automation Server</strong> → copie sua <strong>API Key</strong>.</li><li>Cole o webhook no campo abaixo e salve.</li></ol><p class="hint-line">Exemplo: <code>https://api.pushcut.io/SUA_API_KEY/notifications/MinhaNotificacao</code></p><form method="post" class="notification-form"><input type="hidden" name="csrf" value="<?=app_escape($csrf)?>"><label>Webhook URL<input type="url" name="webhook_url" value="<?=app_escape($notification['webhook_url'])?>" maxlength="512" placeholder="Cole sua URL do Pushcut" autocomplete="off"></label><fieldset><legend>Eventos para notificar</legend><label class="event-option"><input type="checkbox" name="event_signup" value="1" <?=!empty($notification['event_signup'])?'checked':''?>><span><strong>Cadastro realizado</strong><small>Alguém da sua rede se cadastrou — N1, N2 ou N3.</small></span></label><label class="event-option"><input type="checkbox" name="event_deposit" value="1" <?=!empty($notification['event_deposit'])?'checked':''?>><span><strong>Depósito realizado</strong><small>Inclui nome, valor e nível do indicado.</small></span></label><label class="event-option"><input type="checkbox" name="event_sale" value="1" <?=!empty($notification['event_sale'])?'checked':''?>><span><strong>Venda aprovada</strong><small>Inclui o valor da comissão e o nível.</small></span></label></fieldset><div class="button-row"><button class="btn green" name="action" value="notifications_save">Salvar</button><button class="btn outline" name="action" value="notifications_test">Testar</button><button class="btn danger-outline" name="action" value="notifications_remove" formnovalidate>Remover</button></div></form></article></section>
<section class="view" id="view-profile" data-section="profile"><div class="view-heading"><div><small>CONTA</small><h1>Perfil</h1><p>Dados de acesso ao painel de gerente.</p></div></div><article class="surface profile-surface"><span class="profile-avatar"><?=app_escape($managerInitial)?></span><div><h2><?=app_escape($manager['name'])?></h2><p><?=app_escape($manager['email'])?></p></div></article><article class="surface"><form class="profile-form" method="post"><input type="hidden" name="csrf" value="<?=app_escape($csrf)?>"><input type="hidden" name="action" value="profile"><label>Nome<input name="name" maxlength="120" value="<?=app_escape($manager['name'])?>" required></label><label>E-mail<input value="<?=app_escape($manager['email'])?>" readonly></label><label>Senha atual<input type="password" name="current_password" autocomplete="current-password"></label><label>Nova senha<input type="password" name="new_password" minlength="10" maxlength="72" autocomplete="new-password"></label><button class="btn green" type="submit">Salvar perfil</button></form></article></section>
